var Taf = require("taf").wup;

var v = new Taf.List(Taf.String);
v.push("a1");
v.push("a2");

for (var i = 0, len = v.length; i < len; i++) {
	console.log(v.value[i]);
}

for (var key in v.value) {
	console.log(v.value[key]);
}

//JCE编解码示例
var os = new Taf.JceOutputStream();
os.writeList(1, v);
os.getBinBuffer().print();
